export const foundations = [
  ['Typography', '<strong>Lexend</strong> for headings, numbers and buttons; <strong>Atkinson Hyperlegible</strong> (made for readers with low vision) for text. Both are served by OpenDoor itself (no calls to Google). Base 16 px, line height 1.5; paragraphs at most about 70 characters wide.'],
  ['Layout', 'Content up to 72 rem centred on a violet-grey canvas, in white cards with a 2 px border. Dashboards, job details and the employer page use a main column and a side column on wide screens; everything stacks on narrow screens and at large text sizes.'],
  ['Styling', 'Tailwind CSS 4 utilities on top of the shared kit (<code>styles/kit.css</code>) and the tokens in <code>styles/tokens.css</code>. The look follows Francis Ruzgal’s <code>opendoor-ipt</code>; routes, API calls and behaviour are OpenDoor’s own.'],
  ['Buttons', 'Primary (filled purple), secondary (purple outline), small, link-style, danger outline (red outline: Withdraw, Delete, Suspend, Not selected, Remove…) and danger (filled red, inside confirm dialogs). At least 48 px high (44 px small). Busy buttons keep focus and say what is happening ("Saving…").'],
  ['Status', 'Always icon + word + colour, never colour alone: ✓ success (green), ✕ danger (red), ⚠ warning (amber), ○ info (purple), – neutral (grey).'],
  ['Mascot', 'The briefcase mascot (waving on Home, happy after "Application sent", sad on empty and error states, a door while loading). Decorative: it never carries meaning and stays still with reduced motion or Quiet mode.'],
  ['Display settings', 'Text size 100 / 125 / 150 % (root font size), high contrast (darker text, borders and buttons, thicker focus ring) and reduced motion are saved to the account. Quiet mode (no sparkles or decoration, calm colours, no animation), the compact menu and "Keep open" for the display bar stay on the device. Applied as <code>data-text-size</code>, <code>data-contrast</code>, <code>data-motion</code>, <code>data-quiet</code>, <code>data-menu</code> and <code>data-bar</code> on <code>&lt;html&gt;</code>; the system "reduce motion" setting is also respected.'],
  ['Responsive', 'Works at 320 px width and at 200 % text without sideways scrolling; wide tables scroll inside their own labelled box.'],
];

