export const accessibilityRules = [
  'One h1 per screen; after moving to another screen, focus goes to its h1 and the browser tab title changes ("Saved jobs – OpenDoor").',
  '"Skip to main content" is the first link (in the display bar); landmarks: header with the navigation "Main", main, footer.',
  'Step-by-step forms: the "Step n of N · …" heading takes focus on each step, the tab title names the step, and "Next" checks only that step. Tabs follow the ARIA tabs pattern (arrow keys, Home, End) and keep the open tab in the address.',
  'Every input has a visible label; hints and errors sit between the label and the input and are linked to it; required fields say "(required)" in text.',
  'After a failed submit show the error summary at the top and move focus to it.',
  'Status is never shown by colour alone (text + icon + colour). Contrast at least 4.5:1 for text and 3:1 for borders and focus rings.',
  'Charts always have the same data as a table ("Show as a table"), visible labels and values that hover and keyboard focus both show.',
  'Buttons stay focusable while busy or unavailable; they say what is happening ("Saving…", "Please wait…").',
  'Dialogs: focus inside, Escape closes, focus returns to the opener; dangerous confirmations start on Cancel. The welcome tour can always be closed with Escape and never traps the user.',
  'Announce results and saves without moving focus: result counts ("3 jobs found", also "0"), "Your needs are saved.", "Saved. Find it under Saved jobs."',
  'If the focused element disappears (a deleted row), focus goes back to the page h1 instead of the top of the document.',
  'Touch targets at least 44 px; works at 320 px width, 200 % zoom and with the 125/150 % text setting without sideways scrolling.',
  'Decoration (sparkles, icon tiles, accent colours, the mascot) never carries meaning and stays still or disappears in Quiet mode; toggles in the display bar announce their new state.',
  'Dates in Philippine time, written out ("October 12, 2026"); distances as text ("423 m away"), never only on a map.',
  'Read aloud and Voice input appear only where the browser supports them and never start on their own.',
];

